CREATE DATABASE IF NOT EXISTS adls_english_course CHARACTER SET utf8mb4;
USE adls_english_course;
CREATE TABLE IF NOT EXISTS branches(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,city VARCHAR(80),address VARCHAR(255),phone VARCHAR(30),status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(120) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('owner','admin_pusat','admin_cabang','tutor','siswa','ortu') NOT NULL,branch_id INT NULL,phone VARCHAR(30) NULL,hourly_rate DECIMAL(12,2) NULL,status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS classes(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,level VARCHAR(50),schedule VARCHAR(100),tutor_id INT NULL,branch_id INT NULL,type VARCHAR(20) DEFAULT 'offline',meeting_url VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS students(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,parent_name VARCHAR(100),parent_phone VARCHAR(30),class_id INT NULL,level VARCHAR(50),branch_id INT NULL,user_id INT NULL,parent_user_id INT NULL,joined_at DATE NULL,left_at DATE NULL,status VARCHAR(20) DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,category VARCHAR(50),age_group VARCHAR(50),price DECIMAL(12,2) DEFAULT 0,stock INT DEFAULT 0,image VARCHAR(255),description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_orders(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,buyer_name VARCHAR(100) NOT NULL,buyer_phone VARCHAR(30) NULL,branch_id INT NULL,product_id INT NOT NULL,qty INT NOT NULL DEFAULT 1,unit_price DECIMAL(12,2) NOT NULL DEFAULT 0,total_price DECIMAL(12,2) NOT NULL DEFAULT 0,payment_proof VARCHAR(255) NULL,status VARCHAR(20) DEFAULT 'pending',notes VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bills(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,title VARCHAR(120),month VARCHAR(7) NULL,amount DECIMAL(12,2) DEFAULT 0,discount DECIMAL(12,2) DEFAULT 0,due_date DATE,status VARCHAR(20) DEFAULT 'unpaid',payment_method VARCHAR(50) NULL,proof VARCHAR(255),paid_at DATE NULL,notes VARCHAR(255) NULL,branch_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attendance(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,class_id INT NULL,date DATE NOT NULL,status VARCHAR(20) DEFAULT 'hadir',branch_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tutor_attendance(id INT AUTO_INCREMENT PRIMARY KEY,tutor_id INT NOT NULL,class_id INT NULL,branch_id INT NULL,date DATE NOT NULL,check_in VARCHAR(10) NULL,late_minutes INT DEFAULT 0,status VARCHAR(20) DEFAULT 'hadir',notes VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payroll_rules(id INT AUTO_INCREMENT PRIMARY KEY,base_rate DECIMAL(12,2) NOT NULL DEFAULT 100000,transport_allowance DECIMAL(12,2) NOT NULL DEFAULT 15000,late_penalty DECIMAL(12,2) NOT NULL DEFAULT 10000,ontime_bonus DECIMAL(12,2) NOT NULL DEFAULT 150000,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payroll_payments(id INT AUTO_INCREMENT PRIMARY KEY,tutor_id INT NOT NULL,month VARCHAR(7) NOT NULL,branch_id INT NULL,sessions_count INT DEFAULT 0,ontime_count INT DEFAULT 0,late_count INT DEFAULT 0,base_pay DECIMAL(12,2) DEFAULT 0,transport_pay DECIMAL(12,2) DEFAULT 0,penalty_amount DECIMAL(12,2) DEFAULT 0,bonus_amount DECIMAL(12,2) DEFAULT 0,total_amount DECIMAL(12,2) DEFAULT 0,status VARCHAR(20) DEFAULT 'paid',paid_at DATE NULL,notes VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS expenses(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,category VARCHAR(80) NOT NULL,amount DECIMAL(12,2) NOT NULL DEFAULT 0,expense_date DATE NOT NULL,branch_id INT NULL,notes VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learning_reports(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,class_id INT NULL,tutor_id INT NULL,branch_id INT NULL,report_month VARCHAR(7) NOT NULL,report_date DATE NOT NULL,material VARCHAR(255) NOT NULL,homework VARCHAR(255) NULL,formative_score INT NULL,summative_score INT NULL,speaking_score INT NULL,notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reward_claims(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,reward_type VARCHAR(40) DEFAULT 'free_spp_20x100',notes VARCHAR(255) NULL,claimed_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS referrals(id INT AUTO_INCREMENT PRIMARY KEY,referrer_user_id INT NULL,referrer_name VARCHAR(100) NOT NULL,referred_student_name VARCHAR(100) NOT NULL,referred_phone VARCHAR(30) NULL,branch_id INT NULL,commission_amount DECIMAL(12,2) DEFAULT 50000,status VARCHAR(20) DEFAULT 'pending',applied_bill_id INT NULL,notes VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audio_materials(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(150) NOT NULL,level VARCHAR(50) NULL,module_name VARCHAR(120) NULL,audio_url VARCHAR(255) NOT NULL,description TEXT NULL,branch_id INT NULL,created_by INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS video_projects(id INT AUTO_INCREMENT PRIMARY KEY,student_id INT NOT NULL,class_id INT NULL,branch_id INT NULL,user_id INT NULL,month VARCHAR(7) NOT NULL,title VARCHAR(150) NOT NULL,video_url VARCHAR(255) NOT NULL,description TEXT NULL,score INT NULL,feedback VARCHAR(255) NULL,status VARCHAR(20) DEFAULT 'submitted',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS leaves(id INT AUTO_INCREMENT PRIMARY KEY,type VARCHAR(30) NOT NULL,requester_name VARCHAR(100),reason VARCHAR(255),start_date DATE,end_date DATE,status VARCHAR(20) DEFAULT 'pending',branch_id INT NULL,user_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS complaints(id INT AUTO_INCREMENT PRIMARY KEY,from_name VARCHAR(100),subject VARCHAR(150),message TEXT,status VARCHAR(20) DEFAULT 'open',user_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS announcements(id INT AUTO_INCREMENT PRIMARY KEY,info_type VARCHAR(30) DEFAULT 'Pengumuman',letter_no VARCHAR(80) NULL,title VARCHAR(150) NOT NULL,body TEXT,event_date DATE NULL,branch_id INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
